package com.ridex.location.config;
import org.junit.jupiter.api.Test; import org.springframework.cache.Cache; import static org.mockito.Mockito.*; import static org.junit.jupiter.api.Assertions.*;
class LocationCacheErrorHandlerTest { LocationCacheErrorHandler handler=new LocationCacheErrorHandler(); Cache cache=mock(Cache.class); RuntimeException error=new RuntimeException("redis down"); @Test void getFailureIsSwallowed(){assertDoesNotThrow(()->handler.handleCacheGetError(error,cache,"k"));} @Test void putFailureIsSwallowed(){assertDoesNotThrow(()->handler.handleCachePutError(error,cache,"k","v"));} @Test void evictFailureIsSwallowed(){assertDoesNotThrow(()->handler.handleCacheEvictError(error,cache,"k"));} @Test void clearFailureIsSwallowed(){assertDoesNotThrow(()->handler.handleCacheClearError(error,cache));} }
